create table if not exists public.api_usage_events(id bigint generated by default as identity primary key,event_type text not null,estimated_cost_gbp numeric(12,6) not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());alter table public.api_usage_events enable row level security;create index if not exists api_usage_events_created_at_idx on public.api_usage_events(created_at desc);